import{_ as o,c as r,aU as s,a as n}from"./chunks/framework.DP-R0N-M.js";const u=JSON.parse('{"title":"软考系统架构设计师选择题知识点整理","description":"","frontmatter":{},"headers":[],"relativePath":"note/stationmaster/soft-exam/软考系统架构设计师选择题知识点整理.md","filePath":"note/stationmaster/soft-exam/软考系统架构设计师选择题知识点整理.md","lastUpdated":1764166110000}'),g={name:"note/stationmaster/soft-exam/软考系统架构设计师选择题知识点整理.md"};function p(e,t,a,i,_,S){return n(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="软考系统架构设计师选择题知识点整理" tabindex="-1">软考系统架构设计师选择题知识点整理 <a class="header-anchor" href="#软考系统架构设计师选择题知识点整理" aria-label="Permalink to &quot;软考系统架构设计师选择题知识点整理&quot;">​</a></h1><p>001.安全攸关系统在软件需求分析阶段，应提出安全性需求。软件安全性需求是指通过约束软件的行为，使其不会出现（ <strong>软件属性</strong> ）。软件安全需求的获取是根据已知的（ <strong>系统信息</strong> ），如软件危害条件等以及其他一些类似的系统数据和通用惯例，完成通用软件安全性需求的裁剪和特定软件安全性需求的获取工作。</p><p>002.软件设计包括<strong>体系结构设计</strong>、<strong>接口6设计</strong>、<strong>数据设计</strong>和<strong>过程设计</strong>。</p><p>003.基于RUP的软件过程是一个迭代过程。一个开发周期包括<strong>初始</strong>、<strong>细化</strong>、<strong>构建</strong>和<strong>移交</strong>四个阶段，每次通过这四个阶段就会产生一代软件，其中建立完善的架构是（ <strong>细化</strong> ）阶段的任务。采用迭代式开发，在每一轮迭代中都要进行<strong>测试与集成</strong>。</p><p>004.在面向对象设计的原则中，( <strong>依赖倒置</strong> )原则是指抽象不应该依赖于细节，细节应该依赖于抽象，即应针对接口编程，而不是针对实现编程。</p><p>005.按照设计模式的目的进行划分，现有的设计模式可以分为三类：<strong>创建型模式</strong>、<strong>结构型模式</strong>、<strong>行为型模式</strong>。</p><p>006.<strong>创建型模式</strong>主要通过采用抽象类所定义的接口，封装了系统中对象如何创建、组合等信息，其代表有<strong>Singleton模式</strong>等。</p><p>007.<strong>结构型模式</strong>主要用于如何组合己有的类和对象以获得更大的结构，其代表有<strong>Adapter模式</strong>等。</p><p>008.<strong>行为型模式</strong>主要用于对象之间的职责及其提供服务的分配方式，其代表有<strong>Visitor模式</strong>等。</p><p>009.<strong>软件架构风格</strong>是描述某一特定应用领域中系统组织方式的<strong>惯用模式</strong>。架构风格定义了一类架构所共有的特征，主要包括<strong>架构定义</strong>、<strong>架构词汇表</strong>和<strong>架构约束</strong>。</p><p>010.关于软件<strong>架构风格与系统性能</strong>关系的叙述错误的是（<strong>采用面向对象架构风格的系统，可以通过引入对象管理层提高系统性能</strong> ）。</p><p>011.用例之间的关系主要有:<strong>包含</strong>、<strong>扩展</strong>和<strong>泛化</strong>。</p><p>012.架构风格-<strong>数据流风格</strong>：批处理序列、管道-过滤器。</p><p>013.架构风格-<strong>调用/返回风格</strong>：主程序/子程序、面向对象、层次结构。</p><p>014.架构风格-<strong>独立构件风格</strong>：进程通信、事件驱动系统（隐式调用）。</p><p>015.架构风格-<strong>虚拟机风格</strong>：解释器、基于规则的系统。</p><p>016.架构风格-<strong>仓库风格</strong>：数据库系统、超文本系统、黑板系统。</p><p>017.结构化程序设计采用自顶向下、逐步求精及模块化的程序设计方法，通过（ <strong>顺序、分支和循环</strong> ）三种基本的控制结构可以构造出任何单入口单出口的程序。</p><p>018.软件商标权的权利人是指（ <strong>软件注册商标所有人</strong> ）。</p><p>019.软件开发模型大体上分为三种类型。1.是以<strong>软件需求完全确定</strong>为前提的<strong>瀑布模型</strong>；2.是只<strong>提供基本需求</strong>时采用的<strong>迭代式或渐进式模型</strong>，如<strong>喷泉模型</strong>、<strong>螺旋模型</strong>、<strong>统一开发过程</strong>和<strong>敏捷方法</strong>等；3.是<strong>以形式化为基础</strong>的<strong>变换模型</strong>。</p><p>020.要求将业务功能灵活组合形成新的业务功能，属于<strong>自定义类型的业务</strong>，需要<strong>采用虚拟机架构-解释器</strong>。<strong>规则系统</strong>主要适合于<strong>专家系统</strong>。</p><p>021.<strong>软件重用</strong>是指在两次或多次不同的软件开发过程中重复使用相同或相似软件元素的过程。<strong>软件元素</strong>包括<strong>需求分析文档</strong>、<strong>设计过程</strong>、<strong>设计文档</strong>、<strong>程序代码</strong>、<strong>测试用例</strong>、<strong>领域知识</strong>等。</p><p>022.软件质量属性中，（ <strong>Ping/Echo, 进程监视器</strong> ）能提高该系统的<strong>可用性</strong>，（ <strong>队列调度</strong> ）能够提高该系统的<strong>性能</strong>，（ <strong>接口实现分离，信息隐藏</strong> ）能够提高该系统的<strong>可修改性</strong>，（ <strong>限制访问</strong> ）提高系统的<strong>安全性</strong>。</p><p>023.逆向工程导出的信息可以分为实现级、结构级、功能级和领域级四个抽象层次。程序的<strong>抽象语法树</strong>属于（ <strong>实现级</strong> ）；反映程序分量之间相互依赖关系的信息属于（ <strong>结构级</strong> ）。</p><p>024.嵌入式软件设计需要考虑 ( <strong>硬件无关性</strong> ) 以保障软件良好的<strong>可移植性</strong>。</p><p>025.在面向对象中，不同的对象收到同一消息可以产生完全不同的结果，这一现象叫做（ <strong>多态</strong> ）。</p><p>026.绑定是一个把过程调用和响应调用所需要执行的代码加以结合的过程。在一般的程序设计语言中，绑定在编译时进行叫做（ <strong>静态绑定</strong> ）；而（ <strong>动态绑定</strong> ）则在运行时进行，即一个给定的过程调用和执行代码的结合直到调用发生时才进行。</p><p>027.RUP强调采用( <strong>迭代和增量</strong> ) 的方式来开发软件，这样做的好处是( <strong>在软件开发的早期就可以对关键的、影响大的风险进行处理</strong> )。</p><p>028.在软件设计中，（ <strong>概要设计</strong> ）的主要任务是将系统的功能需求分配给软件模块，确定每个模块的功能和调用关系，形成形成软件（ <strong>模块结构图</strong> ）。而为每个具体任务选择适当的技术手段和处理方法的过程称为（ <strong>详细设计</strong> ）。</p><p>029.( <strong>集成测试</strong> )的目的是检查模块之间，以及模块和已集成的软件之间的接口关系，并验证已集成的软件是否符合设计要求。其测试的技术依据是( <strong>软件概要设计文档</strong> )。</p><p>030.<strong>敏捷开发</strong>以<strong>用户的需求进化</strong>为核心，采用<strong>迭代</strong>、<strong>循序渐进</strong>的方法进行软件开发。在敏捷开发中，软件项目在构建初期被切分成多个子项目，各个子项目的成果都经过测试，具备可视、可集成和可运行使用的特征。</p><p>031.<strong>基于架构的软件设计ABSD方法</strong>有<strong>三个基础</strong>，分别是<strong>对系统进行功能分解</strong>、采用（ <strong>架构风格</strong> ）<strong>实现质量属性与商业需求、采用软件模板设计软件结构</strong>。强调采用<strong>视角和视图</strong>来描述<strong>软件架构</strong>，采用<strong>用例和质量属性场景</strong>来描述<strong>需求</strong>。</p><p>032.ABSD方法主要包括架构需求等6个主要活动，其中（ <strong>架构复审</strong> ）活动的目标是标识潜在的风险，及早发现架构设计中的缺陷和错误；（ <strong>架构演化</strong> ）活动针对用户的需求变化，修改应用架构，满足新的需求。</p><p>033.基于架构的软件设计ABSD方法中架构文档化的主要输出结果是（<strong>架构规格说明书</strong>）和（ <strong>架构质量说明书</strong> ）。</p><p>034.分步设计法通常将数据库的设计分为4个阶段。其中（ <strong>概念结构设计</strong> ）是数据库设计的第二阶段，其目标是对<strong>需求说明书</strong>提供的所有数据和处理要求进行抽象与综合处理建立企业数据模型。</p><p>035.<strong>核心层</strong>为网络提供骨干组件和高速交换组件，<strong>高速数据传输</strong>也是核心层的目标；<strong>汇聚层</strong>完成网络<strong>访问策略控制</strong>，<strong>广播域的定义</strong>，<strong>VAN路由等任务</strong>；<strong>接入层</strong>向本地网段提供用户接入，主要提供<strong>广播能力</strong>，<strong>网络分段</strong>，<strong>MAC地址过滤</strong>等。<strong>出口路由</strong>是核心层。</p><p>036.OMG<strong>接口定义语言IDL</strong>文件包含了六种不同的元素，（ <strong>接口描述</strong> ）是一个IDL文件核心的内容，（ <strong>模块定义</strong> ）将映射为Java语言中的包 (package) 或c++语言中的命名空间(Namespace)。</p><p>037.<strong>实时操作系统（Real Time Operating System，简称RTOS）<strong>的任务调度目前主要有</strong>时间分片式</strong>、<strong>轮流查询式</strong>和<strong>优先抢占式</strong>三种，大多数RTOS调度算法都是抢占方式(可剥夺方式) 。</p><p>038.<strong>管理距离</strong>是指一种路由协议的路由可信度。每一种路由协议按可靠性从高到低，依次分配一个<strong>信任等级</strong>，这个信任等级就叫管理距离。一个管理距离是一个从0--255的整数值，0是最可信赖的，而255则意味着不会有业务量通过这个路由。</p><p>039.在数据库系统中，数据的完整性是指数据的（ <strong>有效性、正确性、一致性</strong> ）。</p><p>040.数字签名首先需要生成消息摘要，然后发送方用自己的私钥对报文摘要进行加密， 接收方用发送方的公钥验证真伪。生成消息摘要的目的是（ <strong>防止篡改</strong> ），对摘要进行加密的目的是（ <strong>防止抵赖</strong> ）。</p><p>041.在RUP中采用&quot;4+1&quot;视图模型来描述软件系统的体系结构，最终用户侧重于（ <strong>逻辑视图</strong> ），系统工程师侧重于（ <strong>部署视图</strong> ），系统集成人员侧重于（ <strong>进程视图</strong> ）分析及测试人员侧重于（ <strong>用例视图</strong> ），程序员侧重于（ <strong>实现视图</strong> ）。</p><p>042.与SOA紧密相关的技术，（ <strong>UDDI</strong>）提供了一种服务发布、查找和定位的方法，是服务的信息注册规范。（ <strong>WSDL</strong> ）是对服务进行描述的语言，包含服务实现定义和服务接口定义。（ <strong>SOAP</strong>）定义了服务请求者和服务提供者之间的消息传输规范。</p><p>043.结构化布线系统分为六个子系统，其中水平子系统（ 是指<strong>从楼层管理间到信息插口</strong>这一段，它<strong>连接了垂直干线子系统与工作区子系统</strong> ）。</p><p>044.<strong>入侵检测系统</strong>通常是一个<strong>旁路监听设备</strong>，没有也不需要跨接在任何链路上，无须网络流量流经它便可以工作, 只是监视和分析用户和系统活动。</p><p>045.对Web服务器进行性能评估的主要指标有（ <strong>最大并发连接数, 响应延迟, 吞吐量</strong> ）。</p><p>046.遗产系统的<strong>继承策略</strong>具有（ <strong>低水平,高价值</strong>）的特点, 实施该策略时要（ <strong>完全兼容遗产系统的功能模型和数据模型</strong> ）。</p><p>047.软件重用可以分为<strong>垂直式重用</strong>和<strong>水平式重用</strong>，（ <strong>标准函数库</strong> ）是一种典型的水平式重用。垂直式重用是指<strong>特定领域</strong>的重用,水平式重用是指<strong>通用领域</strong>的重用。</p><p>048.数据仓库4大特点：<strong>面向主题性</strong>：数据按主题组织。<strong>集成性</strong>：消除了源数据中的不一致性，提供整个企业的一致性全局信息。<strong>相对稳定性</strong>(非易失的)：主要进行查询操作，只有少量的修改和删除操作。<strong>反映历史变化</strong>(随着时间变化)：记录了企业从过去某一时刻到当前各个阶段的信息，可对发展历程和未来趋势做定量分析和预测。</p><p>049.成本管理过程包括：<strong>成本估算</strong>、<strong>成本预算</strong>与<strong>成本控制</strong>。成本预算是指将<strong>总的成本估算分配到各项活动和工作包上</strong>，来建立一个成本的基线。<strong>成本估算</strong>是指对<strong>完成项目活动所需资金进行近似的估算</strong>。</p><p>050.项目范围管理中，范围定义的输入包括（ <strong>项目章程、项目范围管理计划、组织过程资产和批准的变更申请</strong> ）。</p><p>051.<strong>螺旋模型</strong>将<strong>瀑布模型</strong>和（ <strong>快速原型</strong> ）结合起来，强调项目的<strong>风险分析</strong>，特别适合大型复杂系统的开发过程。螺旋模型沿着螺线进行若干次迭代，依次经历了<strong>计划指定</strong>、<strong>风险分析</strong>、<strong>工程实施（开发)</strong> 和（ <strong>用户评估</strong> ）四个主要活动。</p><p>052.<strong>装饰模式 (Decorator)<strong>可以再</strong>不修改对象外观</strong>和功能的情况下<strong>添加或者删除对象功能</strong>。优点是:（<strong>比静态继承具有更大的灵活性</strong>）。</p><p>053.<strong>企业信息化方法</strong>主要包括<strong>业务流程重构</strong>、<strong>核心业务应用</strong>、<strong>信息系统建设</strong>、<strong>主题数据库</strong>、<strong>资源管理</strong>、<strong>人力资本投资方法</strong>。</p><p>054.<strong>架构描述语言(ADL)<strong>是一种为明确说明软件系统的概念架构和对这些概念架构建模提供功能的语言。ADL主要包括以下组成部分：<strong>组件</strong>、<strong>组件接口</strong>、<strong>连接件</strong>和</strong>架构配置</strong>。ADL对连接件的重视成为区分ADL和其他建模语言的重要特征之一。</p><p>055.<strong>信号量S</strong>的物理意义为：当S&gt;=0时，表示资源的可用数；当S&lt;=0时，其绝对值表示等待资源的进程数。</p><p>056.关系R与S自然联结运算后的属性列有（ <strong>两个关系属性去重个数</strong> ）个</p><p>057.软件架构风格是描述某一特定应用领域中系统组织方式的惯用模式。一个体系结构定义了一个词汇表和一组（ <strong>约束</strong> ）。架构风格反映领域中众多系统所共有的结构和（ <strong>语义特征</strong> ）。</p><p>058.（ <strong>开放式源码（Open Source）开发方法</strong> ）适用于程序开发人员在地域上分布很广的开发团队。</p><p>059.在面向对象方法中，<strong>信息流</strong>是通过向参与者或内部对象发送消息形成的。（ <strong>顺序图</strong> ）用于描述进出系统的信息流。</p><p>060.ISO开放互连安全体系的5类安全服务包括<strong>鉴别</strong>、<strong>访问控制</strong>、（ <strong>数据机密性</strong> ）、<strong>数据完整性</strong>和<strong>抗抵赖性</strong>。</p><p>061.ERP中的企业资源包括（ <strong>物流，资金流，信息流</strong> ）。其中信息流是核心，而资金流与物流是辅助。四流是在三流的基础之上加了商流。</p><p>062.建筑物综合布线系统中的垂直子系统是指（ <strong>各楼层设备之间的互连系统</strong> ）。</p><p>063.统一软件开发过程(<strong>UP</strong>)是一种基于<strong>面向对象技术</strong>的软件开发过程。其特点是&quot;<strong>用例驱动，以架构为核心,迭代并增量</strong>&quot;。</p><p>064.统一软件开发过程(<strong>UP</strong>)定义了5种通用的框架活动,它们按照过程顺序分别是:<strong>起始阶段、细化阶段、构建阶段、交付阶段和生产阶段</strong>.其中在构建阶段主要产生的文档包括<strong>设计模型</strong>。</p><p>065.<strong>敏感点</strong>是指为了实现某种特定的质量属性，一个或多个系统组件所具有的特性。例如：&quot;对查询请求处理时间的要求将影响系统的数据传输协议和处理过程的设计&quot;。</p><p>066.<strong>权衡点</strong>是指影响多个质量属性的特性，是多个质量属性的敏感点。例如：&quot;更改系统加密的级别将对安全性和性能产生影响&quot;。</p><p>067.<strong>风险点</strong>是指某些做法有一些隐患可能导致一些问题。例如：&quot;业务逻辑的描述尚未达成共识，可能导致部分业务功能模块规则的矛盾，影响系统的可修改性&quot;。</p><p>068.<strong>进程控制块PCB</strong>的组织方式有：<strong>线性表方式，索引表方式，链接表方式</strong>。</p><p>069.Windows操作系统在图形用户界面处理方面采用的是典型的&quot;<strong>事件驱动</strong>&quot;的架构风格。</p><p>070.软件设计包括了四个既独立又相互联系的活动：高质量的（<strong>数据设计</strong>）将改善程序结构和模块划分，降低过程复杂性；（<strong>结构设计</strong>）的主要目标是开发一个模块化的程序结构，并表示出模块间的控制关系；（<strong>接口设计</strong>）描述了软件与用户之间的交互关系。</p><p>071.采用以架构为核心的软件开发方法，在建立软件架构的初期，首要任务是选择一个合适的（ <strong>架构风格</strong> ），在此基础上，开发人员通过架构模型，可以获得关于（ <strong>架构属性</strong> ）的理解，为将来的架构实现与演化过程建立了目标。</p><p>072.为了使一个接口的规范和实现该接口的构件得到广泛应用，需要实现接口的标准化。接口标准是对（ <strong>接口中消息模式、格式和协议</strong> ）的标准化。</p><p>073.衡量计算机的主要性能指标除了字长、存取周期、运算速度之外，通常还包括（ <strong>主存储器容量大小</strong> ），因为其反映了（ <strong>计算机即时存储信息的能力</strong>）。</p><p>074.<strong>项目范围定义</strong>是生产项目计划的基础。</p><p>075.在面向对象分析中，利用（ <strong>用例与用例图</strong> ）表示需求，并从中提炼出中（ <strong>领域模型</strong> ），以上两者形成（ <strong>类图</strong> ），之后再进行后续的开发工作。</p><p>076.基于UML的需求分析过程的基本步骤为：利用（ <strong>用例及用例图</strong> ）表示需求；利用（ <strong>包图及类图</strong> ）表示目标软件系统的总体架构。</p><p>077.企业信息资源集成管理的核心是对企业（ <strong>内部和外部信息流</strong> ）的集成。</p><p>078.基于ODP的架构开发过程中逻辑信息架构包括（ <strong>信息对象，信息行为，信息联合</strong> ）。</p><p>079.软件架构是降低成本、改进质量、按时和按需交付产品的关键因素。软件架构设计需要满足系统的( <strong>质量属性</strong> )，如性能、安全性和可修改性等，并能够指导设计人员和实现人员的工作。</p><p>080.在基于体系结构的软件设计方法中，采用（ <strong>视角和视图</strong> ）来描述软件架构，采用（ <strong>用例</strong> ）来描述功能需求，采用（ <strong>质量场景</strong> ）来描述质量需求。</p><p>081.在架构复审过程中，主要由( <strong>用户代表和领域专家</strong> )决定架构是否满足需求、质量需求是否在设计中得到体现。</p><p>082.软件系统架构是关于软件系统的<strong>结构</strong>、（ <strong>行为</strong> ）和<strong>属性</strong>的高级抽象。</p><p>083.面向服务（Service-Oriented，SO）的开发方法将（ <strong>接口</strong> ）的定义与实现进行解耦，并将跨构件的功能调用暴露出来。</p><p>084.面向服务的开发方法有三个主要的抽象级别，最低层的（ <strong>操作</strong>）代表单个逻辑单元的事物，包含特定的结构化接口；第二层的（<strong>服务</strong>）代表操作的逻辑分组；最高层的（<strong>业务流程</strong>）是为了实现特定业务目标而执行的一组长期运行的动作或者活动。</p><p>085.VRAPS原则包括（ <strong>构想，节奏，预见，协作，简化</strong> ）。</p><p>086.系统移植也是系统构建的一种实现方法，在移植工作中，( <strong>计划阶段</strong> )需要最终确定移植方法。</p><p>087.基于体系结构的开发模型ABSDM把整个软件过程划分为<strong>体系结构需求</strong>、<strong>体系结构设计</strong>、<strong>体系结构文档化</strong>、（ <strong>体系结构复审</strong> ）、（<strong>体系结构实现</strong> ）和<strong>体系结构演化</strong>等6个子过程。（ <strong>体系结构文档化</strong> ）过程的主要输出结果是<strong>体系结构规格说明</strong>和<strong>测试体系结构需求的质量设计说明书</strong>。</p><p>088.为了封装图像操作与照片特征之间的复杂逻辑关系，采用（ <strong>状态模式</strong> ）最为合适。</p><p>089.面向对象的分析模型主要由<strong>顶层架构图</strong>、<strong>用例与用例图</strong>和（ <strong>领域概念模型</strong>）构成：设计模型则包含以（<strong>包图</strong>）表示的软件体系结构图、以<strong>交互图</strong>表示的<strong>用例实现图</strong>、完整精确的类图、描述复杂对象的（<strong>状态图</strong>）和用以描述流程化处理过程的<strong>活动图</strong>等。</p><p>090.CRM系统的四个主要模块包括（ <strong>销售自动化、营销自动化、客户服务与支持、商业智能</strong> ）。</p><p>091.架构权衡分析方法ATAM是一种系统架构评估方法，主要在系统开发之前，针对性能、（ <strong>可用性</strong> ）、安全性和可修改性等质量属性进行评价和折中。</p><p>092.架构权衡分析方法ATAM可以分为4个主要的活动阶段，包括需求收集、（ <strong>架构视图</strong> ）描述、属性模型构造和分析、架构决策与折中，整个评估过程强调以（ <strong>属性</strong> ）作为架构评估的核心概念。</p><p>093.企业信息化涉及对企业管理理念的创新，按照市场发展的要求，对企业现有的管理流程重新整合，管理核心从对（ <strong>财务，物料</strong> ）的管理，转向对（<strong>技术，物资，人力资源</strong>）的管理，并延伸到对企业技术创新、工艺设计、产品设计、生产制造过程的管理，进而还要扩展到对（<strong>客户关系，供应链</strong>）的管理乃至发展到电子商务。</p><p>094.用户提出需求并提供经费，委托软件公司开发软件。双方商定的协议(委托开发合同)中未涉及软件著作权归属，其软件著作权应由( <strong>软件公司</strong> )享有。</p><p>095.分布式数据库两阶段提交协议中的两个阶段是指( <strong>表决阶段、执行阶段</strong> )。</p><p>096.嵌入式处理器类型中不具备内存管理单元(MMU)的是（ <strong>Cortex-M3</strong> ），嵌入式操作系统（ <strong>μC/OS-Ⅱ</strong> ）可以运行在它上面。</p><p>097.软件性能测试有多种不同类型的测试方法，其中，（ <strong>强度测试</strong> ）用于测试在限定的系统下考查软件系统极限运行的情况，（ <strong>容量测试</strong> ）可用于测试系统同时处理的在线最大用户数量。</p><p>098.在数据库设计的需求分析阶段应完成包括（ <strong>数据字典和数据流图</strong> ）在内的文档。</p><p>099.软件过程是制作软件产品的一组活动以及结果，这些活动主要由软件人员来完成，主要包括（ <strong>软件描述、软件开发、软件有效性验证和软件进化</strong> ）。</p><p>100.TCP端口号的作用是（ <strong>对应用层进程的寻址</strong> ）。</p>',101)])])}const d=o(g,[["render",p]]);export{u as __pageData,d as default};
